                    rendered
                        .blockers
                        .into_iter()
                        .map(map_blocker)
                        .collect::<Vec<_>>(),
                    $effects_type::none(),
                ))
                .expect("serialize WorkGraph family parity sample");
                let digest = format!("{:x}", Sha256::digest(json.as_bytes()));
                assert_eq!(digest, $baseline_sha256);
            }
