fn work_graph_append_only_work_graph_events_event_store_promotion_readback_blockers_from(
    preview_report: &WorkGraphAppendOnlyWorkGraphEventsEventStorePromotionPreviewReport,
) -> Vec<WorkGraphEventsEventStorePromotionReadbackBlockerPreview> {
    let all_sources = preview_report
        .event_store_promotion_plans
        .iter()
        .map(|plan| plan.source_surface_id)
        .collect::<Vec<_>>();
    let partial_gap_sources = preview_report
        .blockers
        .iter()
        .find(|blocker| blocker.id == "canonical_adapter_projection_partial_or_gap")
        .map(|blocker| blocker.affected_source_surface_ids.clone())
        .unwrap_or_default();

    vec![
        readback_blocker(
            "append_only_work_graph_events_event_store_promotion_readback_not_executed",
            "high",
            all_sources.clone(),
            "keep event-store promotion readback as a preview until execution is explicitly enabled",
        ),
        readback_blocker(
            "append_only_work_graph_events_event_store_promotion_application_missing",
            "high",
            all_sources.clone(),
            "apply readback-verified event-store promotion contracts into no-persistence outcomes",
