        assert_eq!(cleared.source_count_before, 6);
        assert_eq!(cleared.source_count_after, 0);
        assert_eq!(
            cleared.closure_gate_id,
            WORK_GRAPH_APPEND_ONLY_STORE_ENABLEMENT_PRECONDITION_APPLICATION_PREVIEW_GATE
        );
        assert_eq!(
