    event_store_cutover_operator_review_packet_outcome_count: usize,
) -> Vec<WorkGraphEventsEventStoreCutoverOperatorReviewPacketRerunStagePreview> {
    let partial_gap_count = decision_deltas
        .iter()
        .filter(|decision| {
            decision
                .residual_source_blocker_ids
                .contains(&"canonical_adapter_projection_partial_or_gap")
        })
        .count();

    vec![
        rerun_stage(
            "work_graph_events_event_store_cutover_operator_review_packet_contracts",
            event_store_cutover_operator_review_packet_outcome_count,
            0,
            decision_deltas
                .iter()
                .filter(|decision| {
                    decision
                        .covered_by_event_store_cutover_operator_review_packet_application_preview
                })
                .count(),
            vec![
                "work_graph_events_event_store_cutover_operator_review_packet_readiness_rerun_missing",
            ],
        ),
        rerun_stage(
            "append_only_work_graph_events_persistence",
            decision_deltas.len(),
            0,
            0,
            vec!["append_only_work_graph_events_disabled"],
        ),
        rerun_stage(
            "event_store_cutover_operator_review_packet_readiness",
            decision_deltas.len(),
            0,
            0,
            vec!["append_only_work_graph_events_disabled"],
        ),
        rerun_stage(
            "replay_readback_execution_readiness",
            decision_deltas.len(),
            0,
            0,
            vec!["replay_readback_execution_disabled"],
        ),
        rerun_stage(
            "canonical_adapter_partial_gap_closure",
            partial_gap_count,
            0,
            0,
            vec!["canonical_adapter_projection_partial_or_gap"],
        ),
        rerun_stage(
            "runtime_canonical_adapter_enforcement_dry_run",
            decision_deltas.len(),
            0,
            0,
            vec!["runtime_canonical_adapter_enforcement_disabled"],
        ),
    ]
}

fn source_blocker_ids(
    application_blockers: &[WorkGraphEventsEventStoreCutoverOperatorReviewPacketApplicationBlockerPreview],
    source_surface_id: &'static str,
) -> Vec<&'static str> {
    application_blockers
        .iter()
        .filter(|blocker| {
            !cleared_application_blocker(blocker.id)
                && blocker
                    .affected_source_surface_ids
                    .contains(&source_surface_id)
        })
        .map(|blocker| blocker.id)
        .collect()
}

fn work_graph_events_event_store_cutover_operator_review_packet_rerun_decision(
    contract_ready: bool,
    source_blockers: &[&'static str],
) -> &'static str {
    if !contract_ready {
        "deny_work_graph_events_event_store_cutover_operator_review_packet_application_missing"
    } else if source_blockers.contains(&"append_only_work_graph_events_disabled") {
        "deny_append_only_work_graph_events_disabled"
    } else if source_blockers.contains(&"replay_readback_execution_disabled") {
        "deny_replay_readback_execution_disabled"
    } else if source_blockers.contains(&"canonical_adapter_projection_partial_or_gap") {
        "deny_canonical_adapter_projection_partial_or_gap"
    } else if source_blockers.contains(&"runtime_canonical_adapter_enforcement_disabled") {
        "deny_runtime_canonical_adapter_enforcement_disabled"
    } else {
        "allow_preview_only"
    }
}

fn next_gate_for_decision(decision: &'static str) -> &'static str {
    if decision
        == "deny_work_graph_events_event_store_cutover_operator_review_packet_application_missing"
    {
        WORK_GRAPH_APPEND_ONLY_WORK_GRAPH_EVENTS_EVENT_STORE_CUTOVER_OPERATOR_REVIEW_PACKET_APPLICATION_PREVIEW_GATE
    } else {
        WORK_GRAPH_UNIFIED_PROJECTION_ENFORCEMENT_READINESS_WORK_GRAPH_EVENTS_EVENT_STORE_CUTOVER_OPERATOR_REVIEW_PACKET_RERUN_RECOMMENDED_NEXT_GATE
    }
}

fn cleared_application_blocker(blocker_id: &'static str) -> bool {
    blocker_id
        == "work_graph_events_event_store_cutover_operator_review_packet_readiness_rerun_missing"
}

