fn work_graph_events_persistence_guard_rerun_source_decisions_from(
    previous_decisions: &[WorkGraphEventsReplayReadbackRerunSourceDecisionPreview],
    application_outcomes: &[WorkGraphEventsPersistenceGuardApplicationSourceOutcomePreview],
    application_blockers: &[WorkGraphEventsPersistenceGuardApplicationBlockerPreview],
) -> Vec<WorkGraphEventsPersistenceGuardRerunSourceDecisionPreview> {
    previous_decisions
        .iter()
        .map(|previous| {
            let covered = application_outcomes.iter().any(|outcome| {
                outcome.source_surface_id == previous.source_surface_id
                    && outcome.persistence_guard_contract_ready_preview
                    && !outcome.ready_for_event_store_enablement
            });
            let residual_source_blocker_ids =
                source_blocker_ids(application_blockers, previous.source_surface_id);
            let decision = work_graph_events_persistence_guard_rerun_decision(
                covered,
                &residual_source_blocker_ids,
            );

            WorkGraphEventsPersistenceGuardRerunSourceDecisionPreview {
                source_surface_id: previous.source_surface_id,
                source_category: previous.source_category,
                previous_enforcement_decision: previous
                    .work_graph_events_replay_readback_rerun_enforcement_decision,
                work_graph_events_persistence_guard_rerun_enforcement_decision: decision,
                covered_by_persistence_guard_application_preview: covered,
                persistence_guard_contract_ready: covered,
                persistence_guard_application_applied: false,
                append_only_work_graph_events_enabled: false,
                event_store_enabled: false,
                replay_readback_execution_enabled: false,
                runtime_canonical_adapter_enforcement_enabled: false,
                residual_source_blocker_ids,
                next_required_gate: next_gate_for_decision(decision),
            }
        })
        .collect()
}

fn work_graph_events_persistence_guard_rerun_cleared_blockers_from(
    previous_decisions: &[WorkGraphEventsReplayReadbackRerunSourceDecisionPreview],
    decision_deltas: &[WorkGraphEventsPersistenceGuardRerunSourceDecisionPreview],
) -> Vec<WorkGraphEventsPersistenceGuardRerunClearedBlockerPreview> {
    let before = previous_decisions
        .iter()
        .filter(|decision| {
            decision.work_graph_events_replay_readback_rerun_enforcement_decision
                == "deny_append_only_work_graph_events_disabled"
        })
        .map(|decision| decision.source_surface_id)
        .collect::<Vec<_>>();
    let after_count = decision_deltas
        .iter()
        .filter(|decision| {
            decision.work_graph_events_persistence_guard_rerun_enforcement_decision
                == "deny_work_graph_events_persistence_guard_application_missing"
        })
        .count();

    vec![WorkGraphEventsPersistenceGuardRerunClearedBlockerPreview {
        id: "work_graph_events_persistence_guard_application_required_for_enforcement",
        cleared_source_surface_ids: before.clone(),
        source_count_before: before.len(),
        source_count_after: after_count,
        closure_gate_id:
            WORK_GRAPH_APPEND_ONLY_WORK_GRAPH_EVENTS_PERSISTENCE_GUARD_APPLICATION_PREVIEW_GATE,
    }]
}

fn work_graph_events_persistence_guard_rerun_residual_blockers_from(
    application_blockers: &[WorkGraphEventsPersistenceGuardApplicationBlockerPreview],
) -> Vec<WorkGraphEventsPersistenceGuardRerunResidualBlockerPreview> {
    application_blockers
        .iter()
        .filter(|blocker| !cleared_application_blocker(blocker.id))
        .map(
            |blocker| WorkGraphEventsPersistenceGuardRerunResidualBlockerPreview {
                id: blocker.id,
                severity: blocker.severity,
                category: blocker.category,
                affected_source_surface_ids: blocker.affected_source_surface_ids.clone(),
                required_before_projection_enforcement: true,
                recommended_fix: blocker.recommended_fix,
            },
        )
        .collect()
}

fn work_graph_events_persistence_guard_rerun_stages_from(
    decision_deltas: &[WorkGraphEventsPersistenceGuardRerunSourceDecisionPreview],
    persistence_guard_outcome_count: usize,
) -> Vec<WorkGraphEventsPersistenceGuardRerunStagePreview> {
    let partial_gap_count = decision_deltas
        .iter()
        .filter(|decision| {
            decision
                .residual_source_blocker_ids
                .contains(&"canonical_adapter_projection_partial_or_gap")
        })
        .count();

    vec![
        rerun_stage(
            "work_graph_events_persistence_guard_contracts",
            persistence_guard_outcome_count,
            0,
            decision_deltas
                .iter()
                .filter(|decision| decision.covered_by_persistence_guard_application_preview)
                .count(),
            vec!["work_graph_events_persistence_guard_readiness_rerun_missing"],
        ),
        rerun_stage(
            "append_only_work_graph_events_persistence",
            decision_deltas.len(),
            0,
            0,
            vec!["append_only_work_graph_events_disabled"],
        ),
        rerun_stage(
            "event_store_enablement_readiness",
            decision_deltas.len(),
            0,
            0,
            vec!["append_only_work_graph_events_disabled"],
        ),
        rerun_stage(
            "replay_readback_execution_readiness",
            decision_deltas.len(),
            0,
            0,
            vec!["replay_readback_execution_disabled"],
        ),
        rerun_stage(
            "canonical_adapter_partial_gap_closure",
            partial_gap_count,
            0,
            0,
            vec!["canonical_adapter_projection_partial_or_gap"],
        ),
        rerun_stage(
            "runtime_canonical_adapter_enforcement_dry_run",
            decision_deltas.len(),
            0,
            0,
            vec!["runtime_canonical_adapter_enforcement_disabled"],
        ),
    ]
}

fn source_blocker_ids(
    application_blockers: &[WorkGraphEventsPersistenceGuardApplicationBlockerPreview],
    source_surface_id: &'static str,
) -> Vec<&'static str> {
    application_blockers
        .iter()
        .filter(|blocker| {
            !cleared_application_blocker(blocker.id)
                && blocker
                    .affected_source_surface_ids
                    .contains(&source_surface_id)
        })
        .map(|blocker| blocker.id)
        .collect()
}

fn work_graph_events_persistence_guard_rerun_decision(
    contract_ready: bool,
    source_blockers: &[&'static str],
) -> &'static str {
    if !contract_ready {
        "deny_work_graph_events_persistence_guard_application_missing"
    } else if source_blockers.contains(&"append_only_work_graph_events_disabled") {
        "deny_append_only_work_graph_events_disabled"
    } else if source_blockers.contains(&"replay_readback_execution_disabled") {
        "deny_replay_readback_execution_disabled"
    } else if source_blockers.contains(&"canonical_adapter_projection_partial_or_gap") {
        "deny_canonical_adapter_projection_partial_or_gap"
    } else if source_blockers.contains(&"runtime_canonical_adapter_enforcement_disabled") {
        "deny_runtime_canonical_adapter_enforcement_disabled"
    } else {
        "allow_preview_only"
    }
}

fn next_gate_for_decision(decision: &'static str) -> &'static str {
    if decision == "deny_work_graph_events_persistence_guard_application_missing" {
        WORK_GRAPH_APPEND_ONLY_WORK_GRAPH_EVENTS_PERSISTENCE_GUARD_APPLICATION_PREVIEW_GATE
    } else {
        WORK_GRAPH_UNIFIED_PROJECTION_ENFORCEMENT_READINESS_WORK_GRAPH_EVENTS_PERSISTENCE_GUARD_RERUN_RECOMMENDED_NEXT_GATE
    }
}

fn cleared_application_blocker(blocker_id: &'static str) -> bool {
    blocker_id == "work_graph_events_persistence_guard_readiness_rerun_missing"
}

fn rerun_stage(
    id: &'static str,
    observed_contract_count: usize,
    ready_contract_count_before: usize,
    ready_contract_count_after: usize,
    hard_blocker_ids: Vec<&'static str>,
) -> WorkGraphEventsPersistenceGuardRerunStagePreview {
    WorkGraphEventsPersistenceGuardRerunStagePreview {
        id,
        observed_contract_count,
        ready_contract_count_before,
        ready_contract_count_after,
        hard_blocker_ids,
        enforcement_enabled: false,
        next_gate:
            WORK_GRAPH_UNIFIED_PROJECTION_ENFORCEMENT_READINESS_WORK_GRAPH_EVENTS_PERSISTENCE_GUARD_RERUN_RECOMMENDED_NEXT_GATE,
    }
}

