    #[test]
    fn unified_state_store_preview_declares_collections_and_indexes() {
        let report = hepta_work_graph_unified_state_store_preview_report();
        let collection_ids = report
            .collections
            .iter()
            .map(|collection| collection.id)
            .collect::<Vec<_>>();
        let index_ids = report
            .indexes
            .iter()
            .map(|index| index.id)
            .collect::<Vec<_>>();

        assert_eq!(
            collection_ids,
            [
                "nodes",
                "edges",
                "taskResults",
                "artifacts",
                "approvals",
                "timelineEvents",
            ]
        );
        assert_eq!(
            index_ids,
            [
                "byTraceId",
                "bySourceSurface",
                "byStatus",
                "byEdgeKind",
                "byTaskResultStatus",
                "byTimelineTrace",
            ]
        );
        assert_eq!(report.collection_count, 6);
        assert_eq!(report.index_count, 6);
